// pages/user/[id].js
import { useRouter } from 'next/router';

export default function User({ user }) {
  const router = useRouter();
  return (
    <div>
      <p>Name: {user.name}</p>
      <p>ID from router: {router.query.id}</p>
    </div>
  );
}

export async function getServerSideProps({ params }) {
  const user = { name: 'John' };
  return { props: { user } };
}
